class VirtualDocFS:
    def __init__(self, docs: dict):
        self._docs = docs

    def list_topics(self) -> list[str]:
        return sorted(self._docs.keys())

    def read_section(self, topic: str) -> str:
        return self._docs.get(topic, 'Not found')

    def search_keyword(self, keyword: str) -> list[str]:
        kw = keyword.lower()
        return sorted(t for t, c in self._docs.items() if kw in c.lower())

    def get_tool_specs(self) -> list[dict]:
        return [
            {
                'name': 'list_topics',
                'description': 'List all available documentation topics.',
                'input_schema': {'type': 'object', 'properties': {}, 'required': []},
            },
            {
                'name': 'read_section',
                'description': 'Read the content of a documentation topic.',
                'input_schema': {
                    'type': 'object',
                    'properties': {'topic': {'type': 'string', 'description': 'Topic name'}},
                    'required': ['topic'],
                },
            },
            {
                'name': 'search_keyword',
                'description': 'Find topics whose content contains a keyword (case-insensitive).',
                'input_schema': {
                    'type': 'object',
                    'properties': {'keyword': {'type': 'string', 'description': 'Keyword to search for'}},
                    'required': ['keyword'],
                },
            },
        ]


fs = VirtualDocFS({"auth": "Use API keys for authentication", "setup": "Install the API client"})
print(fs.search_keyword("api"))
print(len(fs.get_tool_specs()))
